87	        boolean bulkSignupWarning = this.clinicService.isBulkSignupWarningActive();
88	        ownerDtos.forEach(ownerDto -> ownerDto.setBulkSignupWarning(bulkSignupWarning));
89	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
